import shutil
import os
from robot.libraries.BuiltIn import BuiltIn
from taf.ul.ettf.scheduler.base_listeners import GlobalListener
from taf.ul.ettf.logger import custom_logger
from taf.ul.ettf.utils.provider import is_set_to_value
from taf.ul.ettf.utils.paths import get_robot_output_dir, get_robot_execution_dir, unique_name, create_dir_if_needed

logger = custom_logger('compressor')


class Compressor(GlobalListener):

    FILENAMES_TO_SKIP = ['log.html', 'output.xml', 'report.html', 'debugs.log']
    LOGS_COMPRESSION_ENABLED = 'LOGS_COMPRESSION'

    def __init__(self):
        super(Compressor, self).__init__()
        self._valid_output_dir = True
        self._output_dir = self._get_logs_dir()

    def _get_logs_dir(self):
        output_dir = get_robot_output_dir()
        execution_dir = get_robot_execution_dir()
        if output_dir in execution_dir or execution_dir in output_dir:
            self._valid_output_dir = False
            logger.warn('Output and execution directories are overlapping, '
                        'logs compression will be disabled')
        return output_dir

    def close(self):
        if self._should_compress():
            logger.info('Compressing started')
            self._compress()
            logger.info('Compressing finished')
        else:
            logger.warn('Logs compression is disabled')

    def _should_compress(self):
        raw_should_compress_value = is_set_to_value(self.LOGS_COMPRESSION_ENABLED)
        return self._valid_output_dir and self._assess_robot_value(raw_should_compress_value)

    def _compress(self):
        output_name = unique_name('execution_logs')
        destination_dir = self._create_destination_directory(output_name)
        self._move_all_logs_to_directory(destination_dir)
        self._archive(destination_dir, output_name)

    def _create_destination_directory(self, output_name):
        dir_path = os.path.join(self._output_dir, output_name)
        create_dir_if_needed(dir_path)
        return dir_path

    def _move_all_logs_to_directory(self, directory):
        for filename in os.listdir(self._output_dir):
            filepath = os.path.join(self._output_dir, filename)
            if filename not in self.FILENAMES_TO_SKIP:
                shutil.move(filepath, directory)

    def _archive(self, dir_path, output_name):
        shutil.make_archive(os.path.join(self._output_dir, output_name), 'zip', dir_path)
        shutil.rmtree(dir_path)

    @staticmethod
    def _assess_robot_value(robot_value):
        return robot_value is None or BuiltIn().convert_to_boolean(robot_value)


compressor = Compressor
